import re
from dataclasses import dataclass, field
from pathlib import Path

from app.generation.hcl import hcl_str, safe_name
from app.generation.templates import RENDERERS
from app.ordering import creation_order, layer_plan

REGION_PATTERN = re.compile(r"^[a-z]{2}(-[a-z]+)+-\d$")
LAYER_PATTERN = re.compile(r"^[a-z0-9-]+$")

HEADER = """\
# Generated by Cloud IaC Agent. Review before applying.
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = __REGION__
}
"""


@dataclass
class GenerationResult:
    main_tf: str
    gaps: list[str] = field(default_factory=list)


@dataclass
class LayeredResult:
    files: dict[str, str]  # relative path -> file text
    plan: dict             # the layer plan this output follows
    gaps: list[str] = field(default_factory=list)


def _check_region(region: str) -> None:
    if not REGION_PATTERN.match(region):
        raise ValueError(f"Not a valid AWS region name: {region!r}")


def _file_text(region: str, blocks: list[str]) -> str:
    header = HEADER.replace("__REGION__", hcl_str(region))
    return header + "\n" + "\n\n".join(blocks) + "\n"


def _local_names(by_id: dict, dependencies: list[dict]) -> dict:
    """One valid, unique Terraform name per resource, across all layers."""
    edges = [(d["from_resource_id"], d["to_resource_id"]) for d in dependencies]
    order = creation_order(list(by_id), edges)
    names, used = {}, set()
    for rid in order:
        r = by_id[rid]
        base = safe_name(r.get("name") or r.get("resource_id"), f"resource_{rid}")
        name = base if base not in used else f"{base}_{rid}"
        used.add(name)
        names[rid] = name
    return names


def _render_layer(layer_ids, by_id, dependencies, local_names, generated):
    """Write the blocks for one folder. Returns (blocks, gaps)."""
    layer_set = set(layer_ids)
    edges = [
        (d["from_resource_id"], d["to_resource_id"])
        for d in dependencies
        if d["from_resource_id"] in layer_set and d["to_resource_id"] in layer_set
    ]
    order = creation_order(sorted(layer_set), edges)

    data_blocks, blocks, gaps = {}, [], []
    for rid in order:
        r = by_id[rid]
        renderer = RENDERERS.get(r["resource_type"])
        if renderer is None:
            gaps.append(f"resource {rid}: type '{r['resource_type']}' is not supported yet")
            continue

        references = []
        for d in dependencies:
            if d["from_resource_id"] != rid or d["relationship"] != "uses_security_group":
                continue
            target = d["to_resource_id"]
            target_row = by_id.get(target)
            if (
                target not in generated
                or target_row is None
                or target_row["resource_type"] != "security_group"
            ):
                gaps.append(f"resource {rid}: needs security group {target}, which was not generated")
            elif target in layer_set:
                references.append(f"aws_security_group.{local_names[target]}.id")
            else:  # lives in another folder: look it up by its existing ID
                local = local_names[target]
                data_blocks[target] = (
                    f'data "aws_security_group" "{local}" {{\n'
                    f"  id = {hcl_str(target_row['resource_id'])}\n"
                    "}"
                )
                references.append(f"data.aws_security_group.{local}.id")

        rendered, rendered_gaps = renderer(r, local_names[rid], {"security_groups": references})
        gaps.extend(rendered_gaps)
        if rendered:
            blocks.extend(rendered)
            generated.add(rid)

    return list(data_blocks.values()) + blocks, gaps


def generate_terraform(
    region: str, resources: list[dict], dependencies: list[dict]
) -> GenerationResult:
    """Everything in one folder."""
    _check_region(region)
    by_id = {r["id"]: r for r in resources}
    local_names = _local_names(by_id, dependencies)
    blocks, gaps = _render_layer(list(by_id), by_id, dependencies, local_names, set())
    return GenerationResult(main_tf=_file_text(region, blocks), gaps=gaps)


def _apply_order_doc(plan: dict) -> str:
    needs: dict[str, list[str]] = {}
    for link in plan["cross_layer_links"]:
        needs.setdefault(link["from_layer"], []).append(link["to_layer"])

    lines = [
        "# Apply order",
        "",
        "Each folder is its own Terraform root with its own state.",
        "Apply them in this order, one folder at a time: run `plan`, review it, then apply.",
        "",
    ]
    for i, layer in enumerate(plan["apply_order"], start=1):
        name = layer["layer"]
        depends = ", ".join(sorted(needs.get(name, []))) or "nothing"
        lines.append(f"{i}. `{name}` ({len(layer['resource_ids'])} resources). Needs: {depends}.")
    if plan["warnings"]:
        lines += ["", "## Warnings", ""] + [f"- {w}" for w in plan["warnings"]]
    return "\n".join(lines) + "\n"


def generate_layers(
    region: str, resources: list[dict], dependencies: list[dict]
) -> LayeredResult:
    """One folder per layer, plus an APPLY_ORDER.md."""
    _check_region(region)
    by_id = {r["id"]: r for r in resources}

    apps = {}
    for r in resources:
        app = r.get("app") or "shared"
        if not LAYER_PATTERN.match(app):  # layer names become folder names
            raise ValueError(f"Not a valid layer name: {app!r}")
        apps[r["id"]] = app

    edges = [(d["from_resource_id"], d["to_resource_id"]) for d in dependencies]
    plan = layer_plan(list(apps.items()), edges)
    local_names = _local_names(by_id, dependencies)

    generated, files, gaps = set(), {}, []
    for layer in plan["apply_order"]:
        name = layer["layer"]
        blocks, layer_gaps = _render_layer(
            layer["resource_ids"], by_id, dependencies, local_names, generated
        )
        gaps.extend(layer_gaps)
        files[f"{name}/main.tf"] = _file_text(region, blocks)
    files["APPLY_ORDER.md"] = _apply_order_doc(plan)
    return LayeredResult(files=files, plan=plan, gaps=gaps)


def write_files(files: dict[str, str], out_dir: Path) -> None:
    """Write generated files, refusing any path that would leave out_dir."""
    root = Path(out_dir).resolve()
    for relative, text in files.items():
        path = (root / relative).resolve()
        if root not in path.parents:
            raise ValueError(f"Refusing to write outside {root}: {relative}")
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")